        key = (r, c)
        if key not in parent:
            parent[key] = par
            center_ok[key] = center
            queue.append(key)

    for r, c in seeds:
        stopped = False
        for cc in range(c, w):
            if blockers[r, cc]:
                add_blocker(r, cc, None, not stopped)
                if not stopped and right_gate(r, cc):
                    stopped = True
            elif not stopped:
                out[r, cc] = 1

    head = 0
    while head < len(queue):
        r, c = queue[head]
        head += 1
        cur = (r, c)

        for dr in (-1, 0, 1):
            rr = r + dr
            if rr < 0 or rr >= h:
                continue

            if dr == 0 and not center_ok.get(cur, True):
