    dirs4 = [(1, 0), (-1, 0), (0, 1), (0, -1)]
    dirs8 = [(dr, dc) for dr in (-1, 0, 1) for dc in (-1, 0, 1) if dr or dc]

    for sr in range(h):
        for sc in range(w):
            if seen[sr, sc] or not open_cell[sr, sc]:
                continue

            comp = []
            q = [(sr, sc)]
            seen[sr, sc] = True
            qi = 0
            while qi < len(q):
                r, c = q[qi]
                qi += 1
                comp.append((r, c))
                for dr, dc in dirs4:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < h and 0 <= nc < w and open_cell[nr, nc] and not seen[nr, nc]:
                        seen[nr, nc] = True
                        q.append((nr, nc))

            in_comp = np.zeros((h, w), dtype=bool)
            for r, c in comp:
                in_comp[r, c] = True

            boundary = []
            for r, c in comp:
                b = (r == 0 or r == h - 1 or c == 0 or c == w - 1)
                if not b:
                    for dr, dc in dirs8:
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < h and 0 <= nc < w and g[nr, nc] == wall:
                            b = True
                            break
                if b:
                    boundary.append((r, c))

            dist = -np.ones((h, w), dtype=int)
            frontier = []
