                dist[p] = 0
                frontier.append(p)

            qi = 0
            while qi < len(frontier):
                r, c = frontier[qi]
                qi += 1
                for dr, dc in dirs4:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < h and 0 <= nc < w and in_comp[nr, nc] and dist[nr, nc] < 0:
                        dist[nr, nc] = dist[r, c] + 1
                        frontier.append((nr, nc))

            by_depth = {}
            for r, c in comp:
