def transform(grid):
    bg = np.bincount(grid.ravel(), minlength=10).argmax()
    counts = np.bincount(grid.ravel(), minlength=10)

    non_bg = [c for c in range(10) if c != bg and counts[c] > 0]
    marker_colors = [c for c in non_bg if counts[c] == min(counts[x] for x in non_bg)]
    marker = marker_colors[0]

    keep_colors = [c for c in non_bg if c != marker]
    border = max(keep_colors, key=lambda c: counts[c])

    h0, w0 = grid.shape
    keep = np.isin(grid, keep_colors)
    seen = np.zeros_like(keep, dtype=bool)
    pieces = []

    for r in range(h0):
        for c in range(w0):
            if keep[r, c] and not seen[r, c]:
                q = [(r, c)]
                seen[r, c] = True
                pts = []
                for rr, cc in q:
                    pts.append((rr, cc))
                    for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        nr, nc = rr + dr, cc + dc
                        if 0 <= nr < h0 and 0 <= nc < w0 and keep[nr, nc] and not seen[nr, nc]:
                            seen[nr, nc] = True
                            q.append((nr, nc))

                rs = [p[0] for p in pts]
                cs = [p[1] for p in pts]
                r1, r2 = min(rs), max(rs)
                c1, c2 = min(cs), max(cs)
                cells = []
                for rr, cc in pts:
                    cells.append((rr - r1, cc - c1, int(grid[rr, cc])))
                pieces.append({
                    "h": r2 - r1 + 1,
                    "w": c2 - c1 + 1,
                    "cells": cells,
                    "n": len(cells)
                })

    area = sum(p["n"] for p in pieces)

    mpts = np.argwhere(grid == marker)
    mr1, mc1 = mpts.min(axis=0)
    mr2, mc2 = mpts.max(axis=0)
    marker_set = {(int(r), int(c)) for r, c in mpts}
    missing = None
    for rr in range(int(mr1), int(mr2) + 1):
        for cc in range(int(mc1), int(mc2) + 1):
            if (rr, cc) not in marker_set:
                missing = (rr, cc)

    mr, mc = missing
    if missing == (mr2, mc2):
        corner = "tl"
    elif missing == (mr1, mc1):
        corner = "br"
    elif missing == (mr1, mc2):
        corner = "bl"
    else:
        corner = "tr"

    def origin_for(H, W):
        if corner == "tl":
            return mr, mc
        if corner == "br":
            return mr - H + 1, mc - W + 1
        if corner == "bl":
            return mr - H + 1, mc
        return mr, mc - W + 1

    dims = []
    for H in range(1, area + 1):
        if area % H == 0:
            W = area // H
            if H <= h0 and W <= w0:
                top, left = origin_for(H, W)
                if 0 <= top and 0 <= left and top + H <= h0 and left + W <= w0:
                    if H >= max(p["h"] for p in pieces) and W >= max(p["w"] for p in pieces):
                        dims.append((H, W))
    dims.sort(key=lambda x: (x[0] > x[1], abs(x[0] - x[1]), x[0]))

    pieces.sort(key=lambda p: -p["n"])

    def solve(H, W):
        board = np.full((H, W), -1, dtype=int)
        used = [False] * len(pieces)

        def ok_place(p, top, left):
            if top < 0 or left < 0 or top + p["h"] > H or left + p["w"] > W:
                return False
            for dr, dc, val in p["cells"]:
                rr, cc = top + dr, left + dc
                if board[rr, cc] != -1:
                    return False
                if (rr == 0 or cc == 0 or rr == H - 1 or cc == W - 1) and val != border:
                    return False
            return True

        def put(p, top, left, val):
            for dr, dc, col in p["cells"]:
                board[top + dr, left + dc] = col if val else -1

        def bt():
            pos = np.argwhere(board == -1)
            if len(pos) == 0:
                return True
            r, c = map(int, pos[0])
            for i, p in enumerate(pieces):
                if used[i]:
                    continue
                for dr, dc, _ in p["cells"]:
                    top, left = r - dr, c - dc
                    if ok_place(p, top, left):
                        used[i] = True
                        put(p, top, left, True)
                        if bt():
                            return True
                        put(p, top, left, False)
                        used[i] = False
            return False

        if bt():
            return board
        return None

    rect = None
    best_dim = None
    for H, W in dims:
        rect = solve(H, W)
        if rect is not None:
            best_dim = (H, W)
            break

    out = np.full_like(grid, bg)
    H, W = best_dim
    top, left = origin_for(H, W)
    out[top:top + H, left:left + W] = rect
    return out
